// Series colours avoid «success» green: a profit series can go below zero,
// and a green loss reads as good news.
func seriesSwatch(j int) string {
	return [...]string{"bg-primary", "bg-warning", "bg-info"}[j%3]
}

func seriesFill(b TrendBar) string {
	if b.Loss {
		return "fill-error"
	}
	return [...]string{"fill-primary", "fill-warning", "fill-info"}[b.Series%3]
}

// hasLoss reports whether any bar on the chart is below zero.
func hasLoss(d TrendData) bool {
	for _, r := range d.Rows {
		for _, b := range r.Column.Bars {
			if b.Loss {
				return true
			}
		}
	}
	return false
}

func chartLabel(d TrendData) string {
	if !d.HasData {
		return d.MetricLabel + ": нет данных за выбранный период"
	}
	return d.MetricLabel
}

func barOpacity(imported bool) string {
	if imported {
		return "0.6"
	}
	return "1"
}

